const history=[{"year": "2021", "revenue": 41.963, "ebit": -3.536, "cfo": null, "source": "https://www.sec.gov/Archives/edgar/data/1943289/000162828024022612/silvacogroupinc-424b4.htm"}, {"year": "2022", "revenue": 46.474, "ebit": -1.873, "cfo": -2.097, "source": "https://www.sec.gov/Archives/edgar/data/1943289/000162828024022612/silvacogroupinc-424b4.htm"}, {"year": "2023", "revenue": 54.246, "ebit": 1.134, "cfo": 1.18, "source": "https://investors.silvaco.com/node/7486/html"}, {"year": "2024", "revenue": 59.68, "ebit": -40.279, "cfo": -19.774, "source": "https://www.sec.gov/Archives/edgar/data/1943289/000162828026017378/svco-20251231.htm"}, {"year": "2025", "revenue": 63.064, "ebit": -45.895, "cfo": -33.906, "source": "https://www.sec.gov/Archives/edgar/data/1943289/000162828026017378/svco-20251231.htm"}];
const text=key=>localizedText('svco-research.'+key);
